=== submission_03.ino ===
   1| // Lab 4 - Button toggles LED
   2| //
   3| // Wiring: push button between D2 and GND, using INPUT_PULLUP so the
   4| // pin is HIGH when released and LOW when pressed.
   5| // The Nano 33 BLE's on-board LEDs are active low, so writing LOW turns
   6| // the LED on and HIGH turns it off.
   7| 
   8| const int BTN = 2;
   9| const int LED = LED_BUILTIN;
  10| 
  11| #define LED_ON   LOW
  12| #define LED_OFF  HIGH
  13| 
  14| const unsigned long DEBOUNCE = 5;   // ms
  15| 
  16| bool isOn = false;            // logical LED state
  17| int lastRead = HIGH;
  18| int confirmed = HIGH;
  19| unsigned long lastChange = 0;
  20| 
  21| void setLed(bool on) {
  22|   digitalWrite(LED, on ? LED_ON : LED_OFF);
  23| }
  24| 
  25| void setup() {
  26|   pinMode(BTN, INPUT_PULLUP);
  27|   pinMode(LED, OUTPUT);
  28|   setLed(false);              // LED off at reset
  29|   Serial1.begin(9600);
  30| }
  31| 
  32| void loop() {
  33|   int r = digitalRead(BTN);
  34| 
  35|   if (r != lastRead) {
  36|     lastChange = millis();
  37|     lastRead = r;
  38|   }
  39| 
  40|   if (millis() - lastChange >= DEBOUNCE && r != confirmed) {
  41|     confirmed = r;
  42|     if (confirmed == LOW) {
  43|       isOn = !isOn;
  44|       setLed(isOn);
  45|       Serial1.println(isOn ? "ON" : "OFF");
  46|     }
  47|   }
  48| }
</student_code>
